var o=[{title:`Muitas causas, muitas respostas`,text:`As pessoas sentem desconforto nas costas por razões diferentes, e até sintomas semelhantes podem ter causas diferentes. Algumas pessoas toleram bem a flexão, enquanto outras preferem um tronco mais neutro. O melhor exercício para si depende dos seus sintomas, da sua capacidade, da sua experiência e de qualquer conselho do seu clínico.`},{title:`Gerir as exigências`,text:`Pratique a estabilização sem suster a respiração durante demasiado tempo, aprenda uma dobra de anca controlada com um peso leve e experimente exercícios com apoio ou no chão quando lhe convierem. Um bird dog suave ou um dead bug treinam o controlo do tronco sem pesos elevados. Nenhuma postura única garante segurança, e manter uma “coluna neutra” não significa bloquear todos os movimentos normais da coluna.`},{title:`Progredir ao longo do tempo`,text:`Se for confortável, torne o treino lentamente mais difícil acrescentando repetições, amplitude ou carga. Tome notas sobre como as costas se sentem durante e depois das sessões. Se os sintomas piorarem, facilite. Em caso de dor persistente, procure aconselhamento profissional; as escolhas de exercício de uma app não o podem substituir.`},{title:`Sinais urgentes`,text:`Alterações novas na bexiga ou no intestino, dormência na zona da virilha, fraqueza grave ou a piorar nas pernas ou dor nas costas depois de uma lesão grave precisam de avaliação médica urgente.`},{title:`Usar o TrainUp`,text:`Acrescente a zona lombar como limitação no Perfil, com uma nota, para que o plano escolha exercícios adequados. Depois de cada treino pode acrescentar notas e indicar dor com a zona do corpo e o exercício. Se um exercício provocar dor, «Sinto dor» termina-o e mantém-no fora dos seus planos até o retomar no Perfil. O TrainUp não diagnostica a causa da dor nas costas.`}];var s=[{label:`NHS: dor lombar e sinais de alerta urgentes`,url:`https://www.nhs.uk/conditions/back-pain/`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};